  protected override void Initialize() {
    this.InitSpecialTokens((int)Tokens.error, (int)Tokens.EOF);
    this.InitStates(states);
    this.InitRules(rules);
    this.InitNonTerminals(nonTerms);
  }

  protected override void DoAction(int action)
  {
    switch (action)
    {
      case 2: // program -> tasks, optional_semicolon, END_OF_FILE
{
			var case_variants = ValueStack[ValueStack.Depth-3].stn as case_variants;

			var case_stmt = new case_node(
				new ident("name"),
				case_variants,
				null,
				CurrentLocationSpan);

			var stmtList = new statement_list(case_stmt, CurrentLocationSpan);

			var blockNode = new block(null, stmtList, CurrentLocationSpan);

			var formalParams = new formal_parameters(
				new typed_parameters(
					new ident_list(new ident("name", CurrentLocationSpan), CurrentLocationSpan),
					new named_type_reference(new ident("String", CurrentLocationSpan), CurrentLocationSpan),
					parametr_kind.none,
					null,
					CurrentLocationSpan), CurrentLocationSpan);

			var header = new procedure_header(
				formalParams,
				new procedure_attributes_list(new List<procedure_attribute>()),
				new method_name(null, null, new ident("CheckTaskT", CurrentLocationSpan), null, CurrentLocationSpan),
				null,
				CurrentLocationSpan);

			root = CurrentSemanticValue.stn = new program_module(null, new uses_list(), new block(new declarations(header, CurrentLocationSpan), stmtList, CurrentLocationSpan), null, CurrentLocationSpan);
		}
        break;
      case 3: // tasks -> task_definition
{
			CurrentSemanticValue.stn = new case_variants(ValueStack[ValueStack.Depth-1].stn as case_variant, CurrentLocationSpan);
		}
        break;
      case 4: // tasks -> tasks, end_of_line, task_definition
{
			CurrentSemanticValue.stn = (ValueStack[ValueStack.Depth-3].stn as case_variants).Add(ValueStack[ValueStack.Depth-1].stn as case_variant, CurrentLocationSpan);
		}
        break;
      case 5: // task_definition -> TASK, task_id, COLON, block
{
		var labelList = new expression_list(ValueStack[ValueStack.Depth-3].ex as ident, CurrentLocationSpan);
		CurrentSemanticValue.stn = new case_variant(labelList, ValueStack[ValueStack.Depth-1].stn as statement_list, CurrentLocationSpan);
    }
        break;
      case 6: // task_id -> INTNUM
{ CurrentSemanticValue.ex = new string_const(ValueStack[ValueStack.Depth-1].ex.ToString(), CurrentLocationSpan); }
        break;
      case 7: // task_id -> STRINGNUM
{ CurrentSemanticValue.ex = new string_const(ValueStack[ValueStack.Depth-1].stn.ToString(), CurrentLocationSpan); }
        break;
      case 8: // task_id -> ident
{ CurrentSemanticValue.ex = new string_const(ValueStack[ValueStack.Depth-1].id.name, CurrentLocationSpan); }
        break;
      case 9: // task_sections -> INDENT, task_section_list, end_of_line, UNINDENT
{
            var stmts = ValueStack[ValueStack.Depth-3].stn as statement_list;
            stmts.left_logical_bracket = ValueStack[ValueStack.Depth-4].ti;
            stmts.right_logical_bracket = ValueStack[ValueStack.Depth-1].ti;
            CurrentSemanticValue.stn.source_context = LexLocation.MergeAll(LocationStack[LocationStack.Depth-3], LocationStack[LocationStack.Depth-2]);
            CurrentSemanticValue.stn = stmts;
        }
        break;
      case 10: // task_section_list -> task_section
{
            CurrentSemanticValue.stn = new statement_list(ValueStack[ValueStack.Depth-1].stn as statement, CurrentLocationSpan);
        }
        break;
      case 11: // task_section_list -> task_section_list, end_of_line, task_section
{
            CurrentSemanticValue.stn = (ValueStack[ValueStack.Depth-3].stn as statement_list).Add(ValueStack[ValueStack.Depth-1].stn as statement, CurrentLocationSpan);
        }
        break;
      case 16: // input_section -> INPUT, COLON, block
{ CurrentSemanticValue.stn = new labeled_statement("input", ValueStack[ValueStack.Depth-1].stn as statement_list, CurrentLocationSpan); }
        break;
      case 17: // check_section -> CHECK, COLON, block
